import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { ScopesEntity } from "#/modules/auth/schema/entities/scopes.entity.ts";
import * as Scopes from "#/modules/auth/schema/types/scopes/index.ts";

/**
 * Repository of Scopes: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class ScopesRepository
  extends EntityRepository<
    ScopesEntity,
    Scopes.Types.ScopesSortableField,
    Scopes.Types.ScopesEditableField,
    Scopes.Types.ScopesSelectableField,
    Scopes.Types.IScopesCreatable
  >
  implements IUpdatableRepository<ScopesEntity, Scopes.Types.IScopesUpdatable>
{
  constructor(
    @InjectRepository(ScopesEntity)
    repository: Repository<ScopesEntity>,
  ) {
    super(repository, Scopes.Config.SCOPES_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(
    id: string,
    data: Scopes.Types.IScopesUpdatable,
  ): Promise<ScopesEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the scopes with this scope hash (unique). */
  async findByScopeHash(
    scopeHash: NonNullable<ScopesEntity["scopeHash"]>,
  ): Promise<ScopesEntity | null> {
    return await this.findOne({ scopeHash });
  }
}
